+			SPA_FORMAT_mediaSubtype, SPA_POD_Id(feed_format.media_subtype),
+			SPA_FORMAT_VIDEO_format, SPA_POD_Id(feed_format.format),
+			SPA_FORMAT_VIDEO_size, SPA_POD_Rectangle(&feed_format.resolution),
+			SPA_FORMAT_VIDEO_framerate, SPA_POD_Fraction(&feed_format.framerate));
+	result = pw_stream_update_params(stream, param, 1);
+	server->sync_wait(proxy);
+	server->thread_unlock();
+	return result == 0;
