+	if (framerate_choice == SPA_CHOICE_Enum) {
+		// Index 0 is the default.
+		for (uint32_t i = 1; i < n_framerates; i++) {
+			feed->add_format(media_subtype, format, resolution, framerate_values[i]);
+		}
+	}
